 function sources(e){const all=[...(e.sources||[]),...(e.lessons||[]).map(id=>sourceFor(id,e))],unique=new Map();all.forEach(v=>{const c=resolve(v.lessonId);const a=c?{lessonId:c.id,title:c.title,grade:c.grade,unit:c.unit}:v;unique.set(a.lessonId,a)});return [...unique.values()]}
